-- Schema 43: receivable/vehicle kinds, account groups, and entry-layer columns for
-- foreign currency and holdings. amount_cents stays CNY cents everywhere.
CREATE TABLE fin_account_groups(id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 40),position INTEGER NOT NULL CHECK(position>=0),revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX fin_account_groups_name ON fin_account_groups(name);
CREATE TABLE new_fin_accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,institution TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL CHECK(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal','receivable','vehicle','credit_card','loan','other_liability')),counted INTEGER NOT NULL CHECK(counted IN (0,1)),opened_on TEXT NOT NULL,closed_on TEXT,notes TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,currency TEXT NOT NULL DEFAULT 'CNY' CHECK(length(currency)=3 AND currency GLOB '[A-Z][A-Z][A-Z]'),purchase_cents INTEGER CHECK(purchase_cents IS NULL OR purchase_cents BETWEEN 0 AND 99999999999),purchased_on TEXT,group_id TEXT REFERENCES fin_account_groups(id),holding_mode INTEGER NOT NULL DEFAULT 0 CHECK(holding_mode IN (0,1)),holding_unit TEXT CHECK(holding_unit IS NULL OR length(holding_unit) BETWEEN 1 AND 8),CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal','receivable','vehicle'))),CHECK(closed_on IS NULL OR closed_on>opened_on),CHECK(kind <> 'property' OR counted = 0),CHECK((purchase_cents IS NULL AND purchased_on IS NULL) OR kind IN ('property','vehicle')),CHECK(holding_mode=0 OR kind IN ('investment','mixed','fund','bond','precious_metal')),CHECK(holding_mode=1 OR holding_unit IS NULL));
CREATE TABLE new_fin_snapshot_entries(snapshot_id TEXT NOT NULL REFERENCES fin_snapshots(id),account_id TEXT NOT NULL REFERENCES fin_accounts(id),state TEXT NOT NULL CHECK(state IN ('entered','unchanged','missing')),amount_cents INTEGER CHECK(amount_cents BETWEEN 0 AND 99999999999),side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL,counted INTEGER NOT NULL CHECK(counted IN (0,1)),original_minor INTEGER CHECK(original_minor IS NULL OR original_minor>=0),fx_rate_micro INTEGER CHECK(fx_rate_micro IS NULL OR fx_rate_micro>0),quantity_e8 INTEGER CHECK(quantity_e8 IS NULL OR quantity_e8>=0),unit_price_e6 INTEGER CHECK(unit_price_e6 IS NULL OR unit_price_e6>=0),PRIMARY KEY(snapshot_id,account_id),CHECK((state='missing')=(amount_cents IS NULL)),CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal','receivable','vehicle'))),CHECK(kind <> 'property' OR counted = 0),CHECK((original_minor IS NULL)=(fx_rate_micro IS NULL)),CHECK((quantity_e8 IS NULL)=(unit_price_e6 IS NULL)),CHECK(state<>'missing' OR (original_minor IS NULL AND quantity_e8 IS NULL)));
INSERT INTO new_fin_accounts(id,name,institution,side,kind,counted,opened_on,closed_on,notes,position,revision,created_at,updated_at,deleted_at) SELECT id,name,institution,side,kind,counted,opened_on,closed_on,notes,position,revision,created_at,updated_at,deleted_at FROM fin_accounts;
INSERT INTO new_fin_snapshot_entries(snapshot_id,account_id,state,amount_cents,side,kind,counted) SELECT snapshot_id,account_id,state,amount_cents,side,kind,counted FROM fin_snapshot_entries;
